"""Display evaluation metrics generated by train_models.py."""
import json
import pandas as pd
import streamlit as st
from preprocessing import MODEL_DIR

st.set_page_config(page_title="Model Evaluation", layout="wide")
st.title("Model Evaluation")
metrics_path = MODEL_DIR / "metrics.json"

if not metrics_path.exists():
    st.error("Evaluation metrics are missing. Run `python train_models.py` first.")
    st.stop()

with open(metrics_path, "r", encoding="utf-8") as f:
    metrics = json.load(f)

st.header("Churn classification")
cls = metrics["classification"]
a, b, c, d = st.columns(4)
a.metric("Accuracy", f'{cls["accuracy"]:.3f}')
b.metric("Precision", f'{cls["precision"]:.3f}')
c.metric("Recall", f'{cls["recall"]:.3f}')
d.metric("F1-score", f'{cls["f1"]:.3f}')

st.caption(
    f'Test set size: {cls["test_size"]}. Positive class: {cls["positive_label"]}.'
)
cm = pd.DataFrame(
    cls["confusion_matrix"],
    index=[f"Actual {label}" for label in cls["labels"]],
    columns=[f"Predicted {label}" for label in cls["labels"]],
)
st.subheader("Confusion matrix")
st.dataframe(cm, use_container_width=True)
st.bar_chart(cm)

st.divider()
st.header("TotalCharges regression")
reg = metrics["regression"]
a, b, c = st.columns(3)
a.metric("MAE", f'{reg["mae"]:.2f}')
b.metric("RMSE", f'{reg["rmse"]:.2f}')
c.metric("R²", f'{reg["r2"]:.3f}')
st.caption(f'Test set size: {reg["test_size"]}.')
